from scipy.ndimage import label
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(a):
    a=np.array(a); H,W=a.shape
    bg=int(Counter(a.flat).most_common(1)[0][0])
    lab,n=label(a!=bg,structure=np.ones((3,3)))
    out=np.full((H,W),bg,int)
    occ=np.zeros_like(out,dtype=bool)
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sc={(int(y),int(x)) for y,x in zip(ys,xs)}
        col=int(a[list(sc)[0]])
        tgt={(y,x+1) for y,x in sc}
        ok=all(0<=ty<H and 0<=tx<W for ty,tx in tgt) and not any(occ[y,x] for y,x in tgt)
        if ok:
            for yy,xx in tgt: out[yy,xx]=col
            occ=tgt.copy()
        else:
            for yy,xx in sc: out[yy,xx]=col
    return out.tolist()
allok=True
for p in range(1,9):
    inp=G[f'Demo pair {p} input']; exp=G[f'Demo pair {p} output']
    o=f(inp)
    ok=(o==exp)
    allok&=ok
    print(p,'match:',ok,'diff:',sum(1 for y in range(len(o)) for x in range(len(o[0])) if o[y][x]!=exp[y][x]))
print('ALL:',allok)

