import numpy as np, os, re
from collections import Counter
from scipy.ndimage import label
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
# packing rule: each component slides right until blocked (collision with another object or wall); order matters - try left-to-right and right-to-left; also vertical adjacency matters (objects touching vertically may block each other)
def comps(a,bg):
    lab,n=label(a!=bg,structure=np.ones((3,3)))
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sc={(int(y),int(x)) for y,x in zip(ys,xs)}
        out.append({'sc':sc,'col':int(a[list(sc)[0]])})
    return out
def sim(inp,order):
    a=np.array(inp); H,W=a.shape
    bg=int(Counter(a.flat).most_common(1)[0][0])
    cs=comps(a,bg)
    idx=sorted(range(len(cs)),key=lambda j: min(x for _,x in cs[j]['sc'])) if order=='L' else sorted(range(len(cs)),key=lambda j:-min(x for _,x in cs[j]['sc']))
    out=np.full((H,W),bg,int); occ=set()
    for j in idx:
        c=cs[j]
        k=0
        while True:
            tgt={(y,x+k) for y,x in c['sc']}
            if any(not(0<=ty<H and 0<=tx<W) for ty,tx in tgt): break
            if tgt & occ: break
            k+=1
        tt={(y,x+k) for y,x in c['sc']}
        for yy,xx in tt:
            out[yy,xx]=c['col']
        occ|=tt
    return out.tolist()
for p in range(1,9):
    inp=G[f'Demo pair {p} input']; exp=G[f'Demo pair {p} output']
    for o in ['L','R']:
        o=sim(inp,o)
        print(p,o,'diff:',sum(1 for y in range(len(o)) for x in range(len(o[0])) if o[y][x]!=exp[y][x]))

